//
{
  "@context": "https://schema.org",
  "@graph": [
    {
      "@type": "WebSite",
      "@id": "https://www.tayninhinfo.com/#website",
      "url": "https://www.tayninhinfo.com/",
      "name": "TNHub Tây Ninh",
      "description": "Cổng thông tin việc làm, bất động sản và kết nối số tỉnh Tây Ninh",
      "publisher": {
        "@type": "Organization",
        "name": "TNHub Tây Ninh",
        "url": "https://www.tayninhinfo.com/",
        "logo": {
          "@type": "ImageObject",
          "url": "https://images.unsplash.com/photo-1500382017468-9049fed747ef?auto=format&fit=crop&w=600&h=600&q=80"
        }
      },
      "potentialAction": {
        "@type": "SearchAction",
        "target": "https://www.tayninhinfo.com/?q={search_term_string}",
        "query-input": "required name=search_term_string"
      }
    },
    {
      "@type": "LocalBusiness",
      "@id": "https://www.tayninhinfo.com/#localbusiness",
      "name": "TNHub - Cổng Kết Nối Số Tây Ninh",
      "url": "https://www.tayninhinfo.com/",
      "telephone": "0908123456",
      "priceRange": "$",
      "address": {
        "@type": "PostalAddress",
        "addressLocality": "Tây Ninh",
        "addressRegion": "Tây Ninh",
        "addressCountry": "VN"
      },
      "geo": {
        "@type": "GeoCoordinates",
        "latitude": 11.3117,
        "longitude": 106.0988
      }
    }
  ]
}
