tailwind.config = {
  darkMode: 'class',
  theme: {
    extend: {
      colors: {
        oracle: {
          red: '#C74634',
          hover: '#B13C2C',
          dark: '#161513',
          warm: '#F1EFED',
          border: '#E0DDD8',
          charcoal: '#312E2B',
          yellow: '#F1B13F'
        },
        tnhub: {
          50: '#fdf3f2',
          100: '#fbe4e2',
          500: '#C74634',
          600: '#B13C2C',
          700: '#9B3325',
          800: '#7E2A1E',
          900: '#161513'
        }
      }
    }
  }
}

head.b:skin:
* {
  border-radius: 0px !important;
}
body {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
  height: 100vh;
  height: 100dvh;
  width: 100vw;
  overflow: hidden;
  background-color: #F1EFED;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  color: #161513;
  display: flex;
}
@media (min-width: 640px) {
  body {
    padding: 12px;
  }
}
@media (min-width: 1024px) {
  body {
    padding: 16px;
  }
}
.custom-scroll::-webkit-scrollbar {
  width: 5px;
  height: 5px;
}
.custom-scroll::-webkit-scrollbar-track {
  background: transparent;
}
.custom-scroll::-webkit-scrollbar-thumb {
  background: #C74634;
  border-radius: 0px !important;
}
[v-cloak] {
  display: none !important;
}

