// ========================================== // INDEXEDDB QUẢN LÝ VÀ LƯU TRỮ VĨNH VIỄN SHORT VIDEOS (KHÔNG BỊ MẤT KHI RELOAD) // ========================================== const SHORTS_DB_NAME = 'tnhub_shorts_db'; const SHORTS_STORE_NAME = 'videos';
const initShortsDB = () => { return new Promise((resolve) => { if (typeof window === 'undefined' || !window.indexedDB) { resolve(null); return; } try { const request = indexedDB.open(SHORTS_DB_NAME, 1); request.onupgradeneeded = (event) => { const dbInst = event.target.result; if (!dbInst.objectStoreNames.contains(SHORTS_STORE_NAME)) { dbInst.createObjectStore(SHORTS_STORE_NAME, { keyPath: 'id' }); } }; request.onsuccess = () => resolve(request.result); request.onerror = () => resolve(null); } catch(e) { resolve(null); } }); };
const saveShortVideoToDB = async (shortItem, fileBlob) => { try { const dbInst = await initShortsDB(); if (!dbInst) return; const tx = dbInst.transaction(SHORTS_STORE_NAME, 'readwrite'); const store = tx.objectStore(SHORTS_STORE_NAME); const record = { ...shortItem }; if (fileBlob) { record.videoBlob = fileBlob; } store.put(record); } catch(e) { console.warn('IndexedDB saveShortVideo error:', e); } };
const loadShortVideosFromDB = async () => { try { const dbInst = await initShortsDB(); if (!dbInst) return []; return new Promise((resolve) => { const tx = dbInst.transaction(SHORTS_STORE_NAME, 'readonly'); const store = tx.objectStore(SHORTS_STORE_NAME); const req = store.getAll(); req.onsuccess = () => { const list = req.result || []; const processed = list.map(item => { if (item.videoBlob) { try { item.url = URL.createObjectURL(item.videoBlob); } catch(e) {} } return item; }); resolve(processed); }; req.onerror = () => resolve([]); }); } catch(e) { return []; } };
// Lấy danh sách video từ cache localStorage hoặc mặc định let initialShorts = [...defaultShortVideos]; try { const cachedShorts = safeGetStorage('tnhub_shorts_videos', null); if (cachedShorts) { const parsed = JSON.parse(cachedShorts); if (Array.isArray(parsed) && parsed.length > 0) { parsed.forEach(p => { if (!initialShorts.some(x => x.id === p.id)) { initialShorts.unshift(p); } }); } } } catch(e) {}
const shortVideosList = ref(initialShorts);
const currentShortVideo = computed(() => { if (!shortVideosList.value || shortVideosList.value.length === 0) { return defaultShortVideos[0]; } const idx = Math.max(0, Math.min(activeShortIndex.value, shortVideosList.value.length - 1)); return shortVideosList.value[idx]; });
const openShortsPage = () => { activeTab.value = 'shorts'; isShortPlaying.value = true; const mainEl = document.querySelector('main'); if (mainEl) mainEl.scrollTop = 0; window.scrollTo(0, 0); setTimeout(() => { const vid = document.getElementById('tiktokShortPlayer'); if (vid) { vid.currentTime = 0; vid.play().catch(() => { isShortMuted.value = true; vid.play(); }); } }, 200); };
const playSelectedShort = (index) => { if (index >= 0 && index < shortVideosList.value.length) { activeShortIndex.value = index; openShortsPage(); } };
const nextShortVideo = () => { if (activeShortIndex.value < shortVideosList.value.length - 1) { activeShortIndex.value++; playCurrentShortVideo(); } };
const prevShortVideo = () => { if (activeShortIndex.value > 0) { activeShortIndex.value--; playCurrentShortVideo(); } };
const playCurrentShortVideo = () => { isShortPlaying.value = true; shortVideoProgress.value = 0; setTimeout(() => { const vid = document.getElementById('tiktokShortPlayer'); if (vid) { vid.currentTime = 0; vid.play().catch(() => {}); } }, 150); };
const togglePlayShortVideo = () => { const vid = document.getElementById('tiktokShortPlayer'); if (!vid) return; if (vid.paused) { vid.play(); isShortPlaying.value = true; } else { vid.pause(); isShortPlaying.value = false; } };
const toggleShortMute = () => { isShortMuted.value = !isShortMuted.value; const vid = document.getElementById('tiktokShortPlayer'); if (vid) vid.muted = isShortMuted.value; };
const toggleLikeShort = (video) => { if (!video) return; if (video.likedByMe) { video.likesCount = Math.max(0, (video.likesCount || 1) - 1); video.likedByMe = false; } else { video.likesCount = (video.likesCount || 0) + 1; video.likedByMe = true; playNotificationSound();
// GỬI NOTIFICATION CHO TÁC GIẢ SHORT VIDEO const targetEmail = (video.authorEmail || '').toLowerCase().trim(); const targetId = video.authorId || video.userId || ''; const myUser = currentUser.value || guestUser.value; const myEmail = (myUser?.email || '').toLowerCase().trim(); const myName = myUser?.displayName || 'Thành viên Tây Ninh'; if (targetEmail && targetEmail !== myEmail) { const captionSnippet = video.caption ? (video.caption.length > 35 ? video.caption.substring(0, 35) + '...' : video.caption) : 'video ngắn'; saveNotificationToFirebase({ id: 'notif_short_like_' + Date.now() + '_' + Math.random().toString(36).substring(2, 6), type: 'short_like', title: '❤️ Có người thả tim video ngắn của bạn', content: myName + ' vừa thả tim video ngắn "' + captionSnippet + '" của bạn.', senderName: myName, senderEmail: myEmail, senderAvatar: myUser?.photoURL || '', receiverEmail: targetEmail, receiverId: targetId, read: false, createdAt: new Date().toISOString() }); } } safeSetStorage('tnhub_shorts_videos', JSON.stringify(shortVideosList.value)); };
