// HÀM LƯU NOTIFICATION LÊN FIREBASE CHO TỪNG USER const saveNotificationToFirebase = async (notif) => { if (!db || !notif) return; const targetEmail = (notif.receiverEmail || notif.targetEmail || (currentUser.value && currentUser.value.email ? currentUser.value.email : (guestUser.value ? guestUser.value.email : ''))).toLowerCase().trim(); const targetId = notif.receiverId || notif.targetId || (currentUser.value && currentUser.value.uid ? currentUser.value.uid : (guestUser.value ? guestUser.value.uid : ''));
const payload = { id: notif.id || ('notif_' + Date.now() + '_' + Math.random().toString(36).substring(2, 7)), type: notif.type || 'system', title: notif.title || 'Thông báo mới', content: notif.content || '', senderName: notif.senderName || 'Hệ thống TNHub', senderEmail: notif.senderEmail || '', senderAvatar: notif.senderAvatar || '', receiverEmail: targetEmail, receiverId: targetId, read: notif.read || false, createdAt: notif.createdAt || new Date().toISOString(), targetPostId: notif.targetPostId || notif.postId || '', scope: notif.scope || 'user' };
// 1. Lưu trực tiếp vào collection 'notifications' trên Firebase theo id try { await setDoc(doc(db, 'notifications', payload.id), payload); console.log('[+] Đã lưu notification lên Firebase notifications collection cho user:', targetEmail || targetId); } catch (e) { console.warn('Lưu notifications Firestore notice:', e.message); }
// 2. Đồng thời đồng bộ qua collection 'messages' với chatId 'user_notifications' (quyền mở) để 100% không bị chặn try { await addDoc(collection(db, 'messages'), { chatId: 'user_notifications', type: 'user_notification', notifId: payload.id, receiverEmail: targetEmail, receiverId: targetId, notification: payload, createdAt: payload.createdAt }); } catch(e) {} };
const addNotification = (notif, saveToCloud = true) => { if (!notif) return; if (!notif.id) notif.id = 'notif_' + Date.now() + '_' + Math.random().toString(36).substring(2, 7); if (notif.read === undefined) notif.read = false;
const existingIdx = notifications.value.findIndex(n => n.id === notif.id); if (existingIdx >= 0) { notifications.value[existingIdx] = { ...notifications.value[existingIdx], ...notif }; } else { notifications.value.unshift(notif); } unreadNotificationCount.value = notifications.value.filter(n => !n.read).length; saveNotificationsToStorage();
if (saveToCloud) { saveNotificationToFirebase(notif); } };
const toggleNotificationDropdown = () => { showNotificationDropdown.value = !showNotificationDropdown.value; };
const updateCombinedNotifs = () => { const map = new Map(); const myEmail = (currentUser.value && currentUser.value.email ? currentUser.value.email : (guestUser.value ? guestUser.value.email : '')).toLowerCase().trim(); const myUid = (currentUser.value && currentUser.value.uid ? currentUser.value.uid : (guestUser.value ? guestUser.value.uid : ''));
// 1. Giữ các thông báo local (notifications.value || []).forEach(n => { if (n && n.id) map.set(n.id, n); });
// 2. Nạp thông báo từ userNotifsList (Firebase) userNotifsList.forEach(n => { if (n && n.id) map.set(n.id, n); });
// 3. Nạp thông báo Global (bài viết mới, thông báo hệ thống) globalNotifsList.forEach(n => { // Không nhận thông báo từ bài đăng do chính mình tạo if (n.senderEmail && n.senderEmail.toLowerCase().trim() === myEmail) return; if (n && n.id && !map.has(n.id)) { map.set(n.id, n); } });
const combined = Array.from(map.values()); combined.sort((a, b) => (b.createdAt || '').localeCompare(a.createdAt || '')); notifications.value = combined; unreadNotificationCount.value = combined.filter(n => !n.read).length; saveNotificationsToStorage(); };
const markAllNotificationsAsRead = async () => { unreadNotificationCount.value = 0; notifications.value.forEach(n => { n.read = true; }); saveNotificationsToStorage(); if (db) { try { for (const n of notifications.value) { if (n.id && !n.id.startsWith('temp_') && n.scope !== 'funded_and_admin') { updateDoc(doc(db, 'notifications', n.id), { read: true }).catch(() => {}); } } const myEmail = (currentUser.value && currentUser.value.email ? currentUser.value.email : (guestUser.value ? guestUser.value.email : '')).toLowerCase().trim(); const myUid = (currentUser.value && currentUser.value.uid ? currentUser.value.uid : (guestUser.value ? guestUser.value.uid : '')); addDoc(collection(db, 'messages'), { chatId: 'user_notifications', type: 'mark_all_notifications_read', receiverEmail: myEmail, receiverId: myUid, createdAt: new Date().toISOString() }).catch(() => {}); } catch (e) { console.warn('Lỗi markAllNotificationsAsRead:', e); } } };
const handleNotificationClick = async (notif) => { if (!notif) return; notif.read = true; unreadNotificationCount.value = notifications.value.filter(n => !n.read).length; saveNotificationsToStorage(); showNotificationDropdown.value = false;
if (db && notif.id && !notif.id.startsWith('temp_') && notif.scope !== 'funded_and_admin') { try { await updateDoc(doc(db, 'notifications', notif.id), { read: true }); } catch(e) {} }
// ĐIỀU HƯỚNG VỀ ĐÚNG TRANG / TÍNH NĂNG TƯƠNG ỨNG KHI CLICK VÀO NOTIFICATION if (notif.type === 'private_chat') { // 1. Tin nhắn riêng 1-1 -> Mở modal chat với người gửi openPrivateChat({ email: notif.senderEmail, name: notif.senderName, avatar: notif.senderAvatar }); } else if (notif.type === 'friend_request') { // Lời mời kết bạn mới -> Mở tab Lời mời kết bạn openFriendsModal('requests'); } else if (notif.type === 'friend_add' || notif.type === 'friend_relation' || notif.type === 'friend_accept') { // Bạn bè & Kết nối -> Mở modal danh sách Bạn bè openFriendsModal('friends'); } else if (notif.type === 'short_video' || notif.type === 'short_comment' || notif.type === 'short_like') { // 3. Short video TikTok -> Chuyển sang trang Shorts openShortsPage(); } else if (notif.type === 'applied_job' || notif.type === 'job_application') { // 4. Tuyển dụng / Hồ sơ ứng tuyển -> Mở tab Việc làm đã ứng tuyển openProfileWithTab('applied'); } else if (notif.type === 'community_chat' || notif.type === 'community') { // 5. Tin nhắn cộng đồng -> Mở drawer Tin Nhắn Realtime openChatDrawer(); } else if ((notif.type === 'comment' || notif.type === 'post_like' || notif.type === 'like' || notif.type === 'comment_like') && notif.targetPostId) { // 6. Bình luận hoặc Thích bài đăng -> Mở chi tiết bài đăng đó openDetailModal({ id: notif.targetPostId }); } else if (notif.type === 'global_new_post' && notif.postId) { // 7. Tin đăng mới VIP / Toàn cầu -> Mở chi tiết bài đăng activeTab.value = 'feed'; if (notif.category && notif.category !== 'all') { activeCategory.value = notif.category; } else { activeCategory.value = 'all'; } const foundCard = cards.value.find(c => c.id === notif.postId); if (foundCard) { if (foundCard.category === 'amthuc') { openFoodDetailPage(foundCard); } else { openDetailModal(foundCard); } } else { openDetailModal({ id: notif.postId }); } } else if (notif.type === 'lottery' || notif.type === 'xoso') { // 8. Kết quả xổ số -> Chuyển sang tab Xổ Số LIVE activeTab.value = 'xoso'; } else if (notif.type === 'metaverse') { // 9. Không gian 3D Metaverse -> Chuyển sang Metaverse activeTab.value = 'metaverse'; } else if (notif.type === 'video' || notif.type === 'youtube_video') { // 10. Video Tây Ninh -> Chuyển sang tab Video activeTab.value = 'video'; } else if (notif.type === 'system_block' || notif.type === 'system_unblock') { // 11. Cảnh báo hệ thống Admin showToast(notif.content, notif.type === 'system_block' ? 'error' : 'success', notif.title); } else if (notif.targetPostId) { openDetailModal({ id: notif.targetPostId }); } };
const clearNotification = async (notifId) => { notifications.value = notifications.value.filter(n => n.id !== notifId); unreadNotificationCount.value = notifications.value.filter(n => !n.read).length; saveNotificationsToStorage(); if (db && notifId) { try { await deleteDoc(doc(db, 'notifications', notifId)); } catch(e) {} } };
const listenRealtimeNotifications = (email, uid) => { if (!db) return; const cleanEmail = (email || (currentUser.value && currentUser.value.email ? currentUser.value.email : (guestUser.value ? guestUser.value.email : ''))).toLowerCase().trim(); const cleanUid = uid || (currentUser.value && currentUser.value.uid ? currentUser.value.uid : (guestUser.value ? guestUser.value.uid : '')); if (!cleanEmail && !cleanUid) return;
// Nạp ngay các notification đã đồng bộ từ Firestore (qua collection messages) cho user này if (allFirebaseMessages && allFirebaseMessages.length > 0) { allFirebaseMessages.forEach(item => { if (item.type === 'user_notification' && item.notification) { const n = item.notification; const toEmail = (item.receiverEmail || n.receiverEmail || '').toLowerCase().trim(); const toId = item.receiverId || n.receiverId || ''; if ((cleanEmail && toEmail === cleanEmail) || (cleanUid && toId === cleanUid)) { addNotification(n, false); } } }); }
if (notifUnsubscribe) { notifUnsubscribe(); notifUnsubscribe = null; } if (globalNotifUnsubscribe) { globalNotifUnsubscribe(); globalNotifUnsubscribe = null; }
const notifsRef = collection(db, 'notifications');
// 1. Kênh thông báo cá nhân lưu trên Firebase cho từng user (theo receiverEmail hoặc receiverId) try { const q = cleanEmail ? query(notifsRef, where('receiverEmail', '==', cleanEmail), limit(50)) : query(notifsRef, where('receiverId', '==', cleanUid), limit(50)); let initialNotifsDone = false; notifUnsubscribe = onSnapshot(q, (snapshot) => { userNotifsList = []; snapshot.forEach(d => { userNotifsList.push({ id: d.id, ...d.data() }); }); updateCombinedNotifs();
if (initialNotifsDone) { snapshot.docChanges().forEach(change => { if (change.type === 'added') { const d = change.doc.data(); playNotificationSound(); const icon = d.type === 'private_chat' ? '💬 ' : (d.type === 'comment' ? '📝 ' : '🔔 '); showToast(icon + (d.title || 'Thông báo mới') + ': ' + (d.content ? d.content.substring(0, 50) : ''), 'info', d.senderName || 'TNHub Tây Ninh'); } }); } initialNotifsDone = true; }, (err) => { // Dự phòng âm thầm đồng bộ qua collection messages }); } catch (e) { console.warn('Setup personal notifications warning:', e); }
// 2. Kênh thông báo GLOBAL dành riêng cho TÀI KHOẢN CÓ NẠP TIỀN & ADMIN if (isAdmin.value || isFundedUser.value) { try { const globalQ = query(notifsRef, where('scope', '==', 'funded_and_admin'), limit(30)); let initialGlobalDone = false; globalNotifUnsubscribe = onSnapshot(globalQ, (snapshot) => { globalNotifsList = []; snapshot.forEach(d => { globalNotifsList.push({ id: d.id, ...d.data() }); }); updateCombinedNotifs();
if (initialGlobalDone) { snapshot.docChanges().forEach(change => { if (change.type === 'added') { const d = change.doc.data(); const myEmail = (currentUser.value && currentUser.value.email ? currentUser.value.email : '').toLowerCase().trim(); if (d.senderEmail && d.senderEmail.toLowerCase().trim() === myEmail) return;
playNotificationSound(); showToast('📢 [Bài đăng mới] ' + (d.senderName || 'Thành viên') + ': ' + (d.title || ''), 'info', 'VIP & Admin'); } }); } initialGlobalDone = true; }, (err) => { console.warn('Global notifications snapshot warning:', err); }); } catch (e) { console.warn('Setup global notifications warning:', e); } } };
// HÀM PHÁT THÔNG BÁO GLOBAL KHI BẤT KỲ AI ĐĂNG BÀI VIẾT MỚI const sendGlobalPostNotification = async (card) => { if (!db || !card) return; const author = card.authorName || (currentUser.value ? currentUser.value.displayName : 'Thành viên Tây Ninh'); const authorEmail = (currentUser.value && currentUser.value.email ? currentUser.value.email : (card.authorEmail || '')).toLowerCase().trim(); const title = card.title || 'Tin đăng mới'; const loc = card.location || 'Tây Ninh'; const categoryLabel = getCategoryLabel(card.category); const priceText = card.price ? (' • Giá: ' + card.price) : '';
const notifPayload = { type: 'global_new_post', scope: 'funded_and_admin', title: 'Bài đăng mới: ' + (title.length > 45 ? title.substring(0, 45) + '...' : title), content: author + ' vừa đăng tin ' + categoryLabel + ': "' + title + '" tại ' + loc + priceText + '. Nhấn xem chi tiết!', postId: card.id, category: card.category || 'all', senderName: author, senderEmail: authorEmail, senderAvatar: card.image || NO_AVATAR_PLACEHOLDER, createdAt: new Date().toISOString(), read: false };
try { // 1. Lưu bản ghi scope 'funded_and_admin' để tất cả tài khoản có nạp tiền và admin nhận realtime await addDoc(collection(db, 'notifications'), notifPayload);
// 2. Đồng thời gửi riêng 1 bản đến đích danh admin (ptquang0968@gmail.com) const adminEmail = 'ptquang0968@gmail.com'; if (authorEmail !== adminEmail) { await addDoc(collection(db, 'notifications'), { ...notifPayload, receiverEmail: adminEmail, title: '👑 [Admin] ' + notifPayload.title }); }
console.log('[+] Đã phát thông báo global bài đăng mới thành công tới tài khoản nạp tiền và Admin!'); } catch(e) { console.warn('sendGlobalPostNotification error:', e); } };
const playNotificationSound = () => { try { const AudioContext = window.AudioContext || window.webkitAudioContext; if (!AudioContext) return; const ctx = new AudioContext(); const osc = ctx.createOscillator(); const gain = ctx.createGain(); osc.connect(gain); gain.connect(ctx.destination); osc.type = 'sine'; osc.frequency.setValueAtTime(587.33, ctx.currentTime); osc.frequency.setValueAtTime(880, ctx.currentTime + 0.1); gain.gain.setValueAtTime(0.15, ctx.currentTime); gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.35); osc.start(); osc.stop(ctx.currentTime + 0.35); } catch (e) {} };
const formatTime = (isoString) => { if (!isoString) return 'Vừa xong'; try { const diff = Math.floor((Date.now() - new Date(isoString).getTime()) / 1000); if (diff < 60) return 'Vừa xong'; if (diff < 3600) return Math.floor(diff / 60) + ' phút trước'; if (diff < 86400) return Math.floor(diff / 3600) + ' giờ trước'; return Math.floor(diff / 86400) + ' ngày trước'; } catch (e) { return 'Gần đây'; } };
