chatMessageInput.value = ''; playNotificationSound();
setTimeout(() => { const box = document.getElementById('communityChatList'); if (box) box.scrollTop = box.scrollHeight; }, 60);
if (db) { try { await addDoc(collection(db, 'messages'), newMsg); } catch (e) { console.warn('Lỗi gửi message Firestore:', e); } }
showToast('Đã gửi tin nhắn lên cộng đồng Tây Ninh!', 'success'); };
const deleteCommunityMessage = async (msg) => { if (!msg) return; if (!isBloggerAdmin.value) { showToast('⚠️ Chỉ có tài khoản Quản trị viên Blogger (ptquang0968@gmail.com) mới có quyền xóa tin nhắn!', 'error', 'Từ Chối Quyền'); return; } if (!confirm('Quản trị viên có chắc chắn muốn xóa vĩnh viễn tin nhắn này khỏi hệ thống?')) { return; }
