// 3. Phát BroadcastChannel để các tab/thiết bị khác xóa ngay lập tức try { if (typeof BroadcastChannel !== 'undefined') { const channel = new BroadcastChannel('tnhub_realtime_chat'); channel.postMessage({ type: 'delete_community_message', messageId: msgId }); } } catch(e) {}
