const selectPin = (target) => { let found = null; if (target && typeof target === 'object') { found = cards.value.find(c => c.id === target.id) || target; } else if (typeof target === 'number') { const idx = target - 1; if (idx >= 0 && idx < cards.value.length) { found = cards.value[idx]; } } else if (typeof target === 'string') { found = cards.value.find(c => c.id === target); }
if (found) { const loc = found.location || 'TP. Tây Ninh'; selectedPinItem.value = { id: found.id, title: found.title, price: found.price, location: loc, image: found.image || 'https://images.unsplash.com/photo-1486406146926-c627a92ad1ab?auto=format&fit=crop&w=120&h=120&q=80' }; const queryLocation = encodeURIComponent(loc + ', Tây Ninh, Việt Nam'); mapEmbedUrl.value = 'https://maps.google.com/maps?q=' + queryLocation + '&t=&z=14&ie=UTF8&iwloc=&output=embed'; showToast('Đang xem vị trí: ' + found.title + ' (' + loc + ')', 'info'); } };
const selectQuickListItem = (item) => { selectPin(item); };
// Lọc thẻ theo Danh mục, Khu vực huyện thị, Tìm kiếm const filteredCards = computed(() => { let list = cards.value;
if (activeCategory.value === 'bookmark') { list = list.filter(c => bookmarks.value.includes(c.id)); } else if (activeCategory.value === 'myposts') { const myEmail = (currentUser.value && currentUser.value.email) || ''; const myUid = (currentUser.value && currentUser.value.uid) || ''; list = list.filter(c => (myEmail && c.authorEmail === myEmail) || (myUid && c.userId === myUid)); } else if (activeCategory.value !== 'all') { list = list.filter(c => c.category === activeCategory.value); }
// Lọc chuyên sâu cho danh mục Ẩm thực & Khách sạn Tây Ninh if (activeCategory.value === 'amthuc' && amthucSubCategory.value !== 'all') { const sub = amthucSubCategory.value; list = list.filter(c => { if (c.subCategory === sub) return true; const text = ((c.title || '') + ' ' + (c.foodType || '') + ' ' + (c.badge || '') + ' ' + (c.description || '')).toLowerCase(); if (sub === 'quan_ngon') return text.includes('quán') || text.includes('bò tơ') || text.includes('bánh canh') || text.includes('đặc sản') || text.includes('nhà hàng') || text.includes('bánh tráng'); if (sub === 'khach_san') return text.includes('khách sạn') || text.includes('hotel') || text.includes('homestay') || text.includes('glamping') || text.includes('nghỉ dưỡng') || text.includes('resort'); if (sub === 'cafe') return text.includes('cà phê') || text.includes('cafe') || text.includes('coffee') || text.includes('trà sữa') || text.includes('view'); if (sub === 'chay') return text.includes('chay') || text.includes('nem bưởi') || text.includes('nấm') || text.includes('long hoa'); return false; }); }
if (activeDistrict.value !== 'all') { list = list.filter(c => c.district === activeDistrict.value || (c.location && c.location.toLowerCase().includes(activeDistrict.value.toLowerCase()))); }
if (searchKeyword.value.trim() !== '') { const kw = searchKeyword.value.toLowerCase().trim(); list = list.filter(c => (c.title && c.title.toLowerCase().includes(kw)) || (c.subtitle && c.subtitle.toLowerCase().includes(kw)) || (c.location && c.location.toLowerCase().includes(kw)) || (c.description && c.description.toLowerCase().includes(kw)) ); }
if (sortAsc.value) { list = [...list].reverse(); }
return list.slice(0, displayLimit.value); });
const totalFilteredCount = computed(() => { let list = cards.value; if (activeCategory.value === 'bookmark') { list = list.filter(c => bookmarks.value.includes(c.id)); } else if (activeCategory.value === 'myposts') { const myEmail = (currentUser.value && currentUser.value.email) || ''; const myUid = (currentUser.value && currentUser.value.uid) || ''; list = list.filter(c => (myEmail && c.authorEmail === myEmail) || (myUid && c.userId === myUid)); } else if (activeCategory.value !== 'all') { list = list.filter(c => c.category === activeCategory.value); }
// Lọc chuyên sâu cho danh mục Ẩm thực & Khách sạn Tây Ninh if (activeCategory.value === 'amthuc' && amthucSubCategory.value !== 'all') { const sub = amthucSubCategory.value; list = list.filter(c => { if (c.subCategory === sub) return true; const text = ((c.title || '') + ' ' + (c.foodType || '') + ' ' + (c.badge || '') + ' ' + (c.description || '')).toLowerCase(); if (sub === 'quan_ngon') return text.includes('quán') || text.includes('bò tơ') || text.includes('bánh canh') || text.includes('đặc sản') || text.includes('nhà hàng') || text.includes('bánh tráng'); if (sub === 'khach_san') return text.includes('khách sạn') || text.includes('hotel') || text.includes('homestay') || text.includes('glamping') || text.includes('nghỉ dưỡng') || text.includes('resort'); if (sub === 'cafe') return text.includes('cà phê') || text.includes('cafe') || text.includes('coffee') || text.includes('trà sữa') || text.includes('view'); if (sub === 'chay') return text.includes('chay') || text.includes('nem bưởi') || text.includes('nấm') || text.includes('long hoa'); return false; }); } if (activeDistrict.value !== 'all') { list = list.filter(c => c.district === activeDistrict.value || (c.location && c.location.toLowerCase().includes(activeDistrict.value.toLowerCase()))); } if (searchKeyword.value.trim() !== '') { const kw = searchKeyword.value.toLowerCase().trim(); list = list.filter(c => (c.title && c.title.toLowerCase().includes(kw)) || (c.subtitle && c.subtitle.toLowerCase().includes(kw)) || (c.location && c.location.toLowerCase().includes(kw)) || (c.description && c.description.toLowerCase().includes(kw)) ); } return list.length; });
const hasMoreCards = computed(() => { return displayLimit.value < totalFilteredCount.value; });
const remainingCardsCount = computed(() => { const diff = totalFilteredCount.value - displayLimit.value; return diff > 0 ? diff : 0; });
const loadMore = () => { displayLimit.value += 12; showToast('Đang hiển thị thêm 12 tin đăng tiếp theo...', 'info'); };
