const openApplyModal = (card) => { if (!currentUser.value || !currentUser.value.uid) { showToast('Vui lòng đăng nhập Google để ứng tuyển việc làm.', 'warning'); loginGoogle(); return; } selectedItem.value = card; if (currentUser.value) { applyForm.value.fullName = userProfile.value?.displayName || currentUser.value.displayName || ''; applyForm.value.phone = userProfile.value?.phone || ''; applyForm.value.email = userProfile.value?.email || currentUser.value.email || ''; } showApplyModal.value = true; };
const openContactModal = (card) => { if (!currentUser.value || !currentUser.value.uid) { showToast('Vui lòng đăng nhập Google để gửi liên hệ.', 'warning'); loginGoogle(); return; } selectedItem.value = card; showContactModal.value = true; };
const openCallModal = (card) => { showPopup('Gọi Điện Nhanh', 'Gọi trực tiếp cho ' + card.title + ' qua Hotline/Zalo: ' + (card.phone || '0908.123.456'), 'info'); };
const postImageDriveStatus = ref(''); const modalNewCommentText = ref('');
const incrementView = (card) => { if (!card) return; card.viewsCount = (card.viewsCount || 0) + 1; if (db && card.id) { try { setDoc(doc(db, 'listings', card.id), { viewsCount: card.viewsCount }, { merge: true }) .catch(e => console.warn('Sync view error:', e)); } catch (e) { console.warn('Sync view:', e); } } };
const toggleLike = (card) => { if (!card || !card.id) return; const cardId = card.id; const currentlyLiked = isPostLiked(cardId); if (currentlyLiked) { // Đã like -> Bỏ like ngay lập tức const idx = myLikedPosts.value.indexOf(cardId); if (idx > -1) myLikedPosts.value.splice(idx, 1); card.likedByMe = false; card.likesCount = Math.max(0, (card.likesCount || 1) - 1); showToast(t('unlikeSuccess') || 'Đã bỏ thích bài đăng', 'info'); } else { // Chưa like -> Like ngay lập tức chỉ với 1 click duy nhất if (!myLikedPosts.value.includes(cardId)) { myLikedPosts.value.push(cardId); } card.likedByMe = true; card.likesCount = (card.likesCount || 0) + 1; showToast(t('likeSuccess') || 'Đã thích bài đăng!', 'success');
