if (postForm.value.category === 'tuyendung') { targetCompanyName = postForm.value.companyName || postForm.value.title || 'Doanh nghiệp tuyển dụng'; // Lấy danh sách vị trí từ form động hoặc desc const formPositions = (postForm.value.positions || []).filter(p => p && p.title && p.title.trim()); if (formPositions.length > 0) { newCardPositions = formPositions.map((p, idx) => ({ id: p.id || ('pos_' + Date.now() + '_' + (idx + 1)), title: p.title.trim(), salary: p.salary || 'Thỏa thuận', count: p.count || '2 - 3 người', experience: p.experience || 'Không yêu cầu', deadline: p.deadline || '30/05/2026', desc: p.desc || ('Vị trí ' + p.title.trim() + ' tại ' + targetCompanyName) })); } else { // Dự phòng từ description nếu có dạng vị trí const desc = postForm.value.description || ''; const posRegex = /Vị trí\s*(\d+)[:\s]*(.+?)(?=(?:Vị trí\s*\d+|$))/gis; let match; while ((match = posRegex.exec(desc)) !== null) { const pNum = match[1]; const pContent = match[2].trim(); const lines = pContent.split('\n').map(l => l.trim()).filter(Boolean); const pTitle = lines[0] || ('Vị trí ' + pNum); const restText = lines.slice(1).join('\n'); let pSalary = postForm.value.price || 'Thỏa thuận'; const salMatch = pContent.match(/(?:Lương|Mức lương|Thu nhập)[:\s]*([^\n]+)/i); if (salMatch) pSalary = salMatch[1].trim(); let pCount = '2 - 3 người'; const countMatch = pContent.match(/(?:Số lượng|Tuyển)[:\s]*([^\n|]+)/i); if (countMatch) pCount = countMatch[1].trim(); let pDeadline = '30/05/2026'; const deadMatch = pContent.match(/(?:Hạn nộp|Hạn)[:\s]*([^\n|]+)/i); if (deadMatch) pDeadline = deadMatch[1].trim();
