// ========================================== // CÁC HÀM XỬ LÝ ADMIN CRAWLER // ========================================== const openCrawlerModal = () => { if (!isBloggerAdmin.value) { showToast('⚠️ Tính năng Crawler Hub chỉ dành riêng cho tài khoản Admin của Blogger (ptquang0968@gmail.com)!', 'error', 'Từ Chối Quyền'); return; } showCrawlerModal.value = true; };
