const loadAppliedJobs = async () => { try { const key = getAppliedStorageKey(); const localData = localStorage.getItem(key); if (localData) { try { appliedJobsList.value = JSON.parse(localData) || []; } catch (e) { appliedJobsList.value = []; } } else { appliedJobsList.value = []; }
// Đồng bộ từ Cloud Firestore nếu đã đăng nhập if (currentUser.value && currentUser.value.uid && db) { try { const appsCol = collection(db, 'users', currentUser.value.uid, 'applied_jobs'); const snap = await getDocs(appsCol); if (!snap.empty) { const remoteJobs = []; snap.forEach(docSnap => { remoteJobs.push({ id: docSnap.id, ...docSnap.data() }); }); if (remoteJobs.length > 0) { const map = new Map(); appliedJobsList.value.forEach(j => map.set(j.jobId || j.id, j)); remoteJobs.forEach(j => map.set(j.jobId || j.id, j)); appliedJobsList.value = Array.from(map.values()).sort((a, b) => new Date(b.appliedAt || 0) - new Date(a.appliedAt || 0)); saveAppliedJobsToStorage(); } } } catch (err) { console.warn('Sync applied jobs from Firestore:', err); } } } catch (err) { console.warn('Error loading applied jobs:', err); } };
