// BẠN BÈ FUNCTIONS (CHUẨN HÓA ĐỊNH DANH & ĐỒNG BỘ MULTI-DEVICE CLOUD) const getFriendKey = (target) => { if (!target) return ''; if (typeof target === 'string') return target.trim().toLowerCase(); return ( target.authorEmail || target.email || target.userId || target.uid || target.authorId || (target.id ? String(target.id) : '') || target.authorName || target.displayName || target.name || '' ).trim().toLowerCase(); };
