const loadFriends = async (userObj) => { try { let user = userObj || currentUser.value; if (!user) { try { const cached = safeGetStorage('tnhub_auth_user'); if (cached) user = JSON.parse(cached); } catch(e) {} } if (!user) user = guestUser.value;
const uid = user ? (user.uid || '').toLowerCase().trim() : ''; const email = user ? (user.email || '').toLowerCase().trim() : '';
// 1. Tải từ localStorage const saved = (uid && uid !== 'guest' ? localStorage.getItem('tnhub_friends_' + uid) : null) || (email ? localStorage.getItem('tnhub_friends_' + email) : null) || localStorage.getItem('tnhub_friends'); if (saved) { try { friendsList.value = JSON.parse(saved) || []; } catch (parseErr) { friendsList.value = []; } } else { friendsList.value = []; }
// 2. Đồng bộ 2 CHIỀU TỪ allFirebaseMessages if (allFirebaseMessages && allFirebaseMessages.length > 0 && (email || (uid && uid !== 'guest'))) { const relationMap = new Map(); const incomingReqMap = new Map(); const sentReqMap = new Map();
// Sắp xếp theo thứ tự thời gian tăng dần const sortedFriendMsgs = allFirebaseMessages .filter(m => m.type === 'friend_relation') .slice() .sort((a, b) => new Date(a.createdAt || 0) - new Date(b.createdAt || 0));
sortedFriendMsgs.forEach(m => { const u1Email = (m.user1Email || '').toLowerCase().trim(); const u1Uid = (m.user1Uid || '').toLowerCase().trim(); const u2Email = (m.user2Email || '').toLowerCase().trim(); const u2Uid = (m.user2Uid || '').toLowerCase().trim();
const isMeUser1 = (email && u1Email === email) || (uid && uid !== 'guest' && u1Uid === uid); const isMeUser2 = (email && u2Email === email) || (uid && uid !== 'guest' && u2Uid === uid);
if (!isMeUser1 && !isMeUser2) return;
const otherUser1 = { id: u1Email || u1Uid, key: u1Email || u1Uid, name: m.user1Name || 'Thành viên Tây Ninh', email: m.user1Email, avatar: m.user1Avatar || 'https://images.unsplash.com/photo-1535713875002-d1d0cf377fde?auto=format&fit=crop&w=80&q=80', location: m.user1Location || 'Tây Ninh', uid: m.user1Uid, requestedAt: m.createdAt, addedAt: m.createdAt };
const otherUser2 = { id: u2Email || u2Uid, key: u2Email || u2Uid, name: m.user2Name || 'Thành viên Tây Ninh', email: m.user2Email, avatar: m.user2Avatar || 'https://images.unsplash.com/photo-1535713875002-d1d0cf377fde?auto=format&fit=crop&w=80&q=80', location: m.user2Location || 'Tây Ninh', uid: m.user2Uid, requestedAt: m.createdAt, addedAt: m.createdAt };
const key1 = getFriendKey(otherUser1); const key2 = getFriendKey(otherUser2);
if (m.action === 'request') { if (isMeUser2) { incomingReqMap.set(key1, otherUser1); } else if (isMeUser1) { sentReqMap.set(key2, otherUser2); } } else if (m.action === 'accept' || m.action === 'add') { if (isMeUser2) { incomingReqMap.delete(key1); relationMap.set(key1, otherUser1); } else if (isMeUser1) { sentReqMap.delete(key2); relationMap.set(key2, otherUser2); } } else if (m.action === 'reject') { if (isMeUser2) { incomingReqMap.delete(key1); } else if (isMeUser1) { sentReqMap.delete(key2); } } else if (m.action === 'remove') { if (isMeUser2) { incomingReqMap.delete(key1); relationMap.delete(key1); } else if (isMeUser1) { sentReqMap.delete(key2); relationMap.delete(key2); } } });
incomingFriendRequests.value = Array.from(incomingReqMap.values()); sentFriendRequests.value = Array.from(sentReqMap.values());
relationMap.forEach((val, k) => { const existingIdx = friendsList.value.findIndex(f => getFriendKey(f) === k); if (existingIdx === -1) { friendsList.value.unshift(val); } else { friendsList.value[existingIdx] = { ...friendsList.value[existingIdx], ...val }; } });
friendsList.value = friendsList.value.filter(f => { const k = getFriendKey(f); return !k || relationMap.has(k) || !sortedFriendMsgs.some(m => m.action === 'remove' && (getFriendKey(m.user1Email) === k || getFriendKey(m.user2Email) === k)); });
saveFriendsToStorage(user); } } catch (e) { console.warn('Load friends error:', e); } };
