const hasIncomingFriendRequest = (target) => { if (!target) return false; const key = getFriendKey(target); if (!key) return false; return incomingFriendRequests.value.some(r => { const rKey = getFriendKey(r); return rKey && (rKey === key || (r.email && r.email.toLowerCase() === key)); }); };
const hasSentFriendRequest = (target) => { if (!target) return false; const key = getFriendKey(target); if (!key) return false; return sentFriendRequests.value.some(r => { const rKey = getFriendKey(r); return rKey && (rKey === key || (r.email && r.email.toLowerCase() === key)); }); };
