// Realtime notification cho người nhận saveNotificationToFirebase({ id: 'notif_fr_req_' + Date.now(), type: 'friend_request', title: '🤝 Lời mời kết bạn mới', content: myName + ' đã gửi cho bạn một lời mời kết bạn trên TNHub!', senderName: myName, senderEmail: myEmail, senderAvatar: myAvatar, receiverEmail: email, receiverId: targetUid, read: false, createdAt: new Date().toISOString() }); } };
