// CHUẨN HÓA ĐỊNH DANH NGƯỜI DÙNG CHO CHAT 1-1 REALTIME const getUserChatKey = (obj) => { if (!obj) return ''; if (typeof obj === 'string') { const s = obj.trim().toLowerCase(); return s; } const email = obj.email || obj.authorEmail || obj.senderEmail || obj.receiverEmail || ''; if (email && email.includes('@')) { return email.trim().toLowerCase(); } const uid = obj.uid || obj.userId || obj.authorId || obj.senderId || obj.receiverId || obj.id || ''; return uid.toString().trim().toLowerCase(); };
const getChatId = (userA, userB) => { const k1 = getUserChatKey(userA).replace(/[^a-zA-Z0-9]/g, '_'); const k2 = getUserChatKey(userB).replace(/[^a-zA-Z0-9]/g, '_'); if (!k1 || !k2) return 'general_chat'; return [k1, k2].sort().join('___chat___'); };
// SINH MÃ KEY MẶC ĐỊNH BẢO MẬT CHO MỖI PHÒNG CHAT (ROOM KEY) const getRoomDefaultKey = (chatId) => { if (!chatId) return 'TN-6888'; let hash = 0; for (let i = 0; i < chatId.length; i++) { hash = ((hash << 5) - hash) + chatId.charCodeAt(i); hash |= 0; } const num = Math.abs(hash) % 90000 + 10000; return 'TN-' + num; };
const getRoomKeyForChat = (chatId) => { // 1. Kiểm tra nếu trong tin nhắn của phòng có roomKey do người gửi lưu const msgWithKey = allFirebaseMessages.slice().reverse().find(m => m.chatId === chatId && m.roomKey); if (msgWithKey && msgWithKey.roomKey) { return msgWithKey.roomKey; } // 2. Kiểm tra nếu có custom key lưu tại localStorage const localCustomKey = safeGetStorage('tnhub_room_key_' + chatId, null); if (localCustomKey) return localCustomKey; // 3. Mặc định sinh mã theo chatId return getRoomDefaultKey(chatId); };
const copyRoomKey = () => { if (!currentRoomKey.value) return; const partnerName = (activeChatPartner.value && activeChatPartner.value.name) ? activeChatPartner.value.name : 'bạn'; const textToShare = '[TNHub Private Chat] Mã khóa phòng trò chuyện riêng tư của tôi với ' + partnerName + ' là: ' + currentRoomKey.value + '. Bạn hãy mở TNHub, vào phòng chat và nhập mã này để mở khóa trò chuyện nhé!'; try { if (navigator && navigator.clipboard && navigator.clipboard.writeText) { navigator.clipboard.writeText(textToShare); } else { const ta = document.createElement('textarea'); ta.value = textToShare; document.body.appendChild(ta); ta.select(); document.execCommand('copy'); document.body.removeChild(ta); } showToast('Đã sao chép mã Key: ' + currentRoomKey.value + '. Hãy gửi cho ' + partnerName + '!', 'success', 'Sao Chép Mã Key'); } catch(e) { showToast('Mã Key phòng: ' + currentRoomKey.value, 'info'); } };
const unlockPrivateRoom = () => { const input = (enteredRoomKey.value || '').trim().toUpperCase(); const target = (currentRoomKey.value || '').trim().toUpperCase(); if (!input) { roomKeyInputError.value = 'Vui lòng nhập mã Key của phòng chat!'; return; } const cleanInput = input.replace(/[^A-Z0-9]/g, ''); const cleanTarget = target.replace(/[^A-Z0-9]/g, '');
if (cleanInput === cleanTarget) { isPrivateRoomUnlocked.value = true; roomKeyInputError.value = ''; const sender = (currentUser.value && currentUser.value.uid) ? currentUser.value : guestUser.value; const chatId = getChatId(sender, activeChatPartner.value); safeSetStorage('tnhub_unlocked_' + chatId, 'unlocked'); showToast('Mở khóa phòng chat riêng tư thành công!', 'success', 'Mở Khóa Thành Công'); setTimeout(() => { const box = document.getElementById('privateChatBox'); if (box) box.scrollTop = box.scrollHeight; }, 100); } else { roomKeyInputError.value = 'Mã Key không chính xác! Vui lòng hỏi lại người gửi để nhận đúng mã.'; showToast('Mã Key không chính xác. Vui lòng thử lại!', 'error', 'Sai Mã Khóa'); } };
const relockPrivateRoom = () => { if (!activeChatPartner.value) return; const sender = (currentUser.value && currentUser.value.uid) ? currentUser.value : guestUser.value; const chatId = getChatId(sender, activeChatPartner.value); safeSetStorage('tnhub_unlocked_' + chatId, 'locked'); isPrivateRoomUnlocked.value = false; enteredRoomKey.value = ''; roomKeyInputError.value = ''; showToast('Đã khóa lại cuộc trò chuyện riêng tư này.', 'info', 'Đã Khóa'); };
// allFirebaseMessages is already declared at the top of setup()
const loadPrivateMessagesForChat = (chatId) => { const sender = (currentUser.value && currentUser.value.uid) ? currentUser.value : guestUser.value; const myEmail = (sender.email || sender.uid || '').toLowerCase().trim();
const filtered = allFirebaseMessages.filter(m => m.chatId === chatId); privateMessages.value = filtered.map(m => ({ ...m, isMe: (myEmail && m.senderEmail && m.senderEmail.toLowerCase() === myEmail) || (sender.uid && m.senderId === sender.uid) })); setTimeout(() => { const box = document.getElementById('privateChatBox'); if (box) box.scrollTop = box.scrollHeight; }, 80); };
const openPrivateChat = (target) => { if (!target) return;
const sender = (currentUser.value && currentUser.value.uid) ? currentUser.value : guestUser.value;
// Hỗ trợ mọi loại target: card bài đăng, friend, user profile, notification const partnerEmail = (target.email || target.authorEmail || target.senderEmail || (target.rawTarget ? target.rawTarget.authorEmail : '') || '').toLowerCase().trim(); const partnerName = target.name || target.displayName || target.authorName || target.author || target.senderName || (partnerEmail ? partnerEmail.split('@')[0] : 'Người đăng'); const partnerAvatar = target.avatar || target.photoURL || target.authorAvatar || target.senderAvatar || 'https://images.unsplash.com/photo-1535713875002-d1d0cf377fde?auto=format&fit=crop&w=80&q=80'; const partnerId = partnerEmail || target.userId || target.uid || (target.id ? ('user_' + target.id) : 'partner_' + Date.now());
