// THÔNG BÁO CHO PHÍA NGƯỜI GỬI (SENDER NOTIFICATION) const sentSnippet = text.length > 35 ? text.substring(0, 35) + '...' : text; showToast('✅ Đã gửi tin nhắn đến ' + (activeChatPartner.value.name || 'đối phương') + ': "' + sentSnippet + '"', 'success', 'Đã Gửi Tin Nhắn');
// Thêm và lưu thông báo người gửi lên Firebase addNotification({ id: 'notif_sent_' + Date.now(), type: 'private_chat_sent', title: 'Đã gửi tin nhắn đến ' + (activeChatPartner.value.name || 'đối phương'), content: text, senderName: 'Bạn', senderEmail: myEmail, senderAvatar: sender.photoURL || '', receiverName: activeChatPartner.value.name, receiverEmail: myEmail, receiverId: sender.uid || '', read: true, createdAt: new Date().toISOString() }, true);
// Lưu thông báo lên Firebase cho phía người nhận saveNotificationToFirebase({ id: 'notif_rcv_' + Date.now(), type: 'private_chat', title: 'Tin nhắn từ ' + (sender.displayName || 'Thành viên Tây Ninh'), content: text, senderName: sender.displayName || 'Thành viên Tây Ninh', senderEmail: myEmail, senderAvatar: sender.photoURL || '', receiverEmail: partnerEmail, receiverId: activeChatPartner.value.id || '', read: false, createdAt: new Date().toISOString() });
// PHÁT BROADCAST ĐỒNG BỘ REALTIME CẢ 2 BÊN QUA BROADCASTCHANNEL & LOCALSTORAGE try { if (typeof BroadcastChannel !== 'undefined') { const channel = new BroadcastChannel('tnhub_realtime_chat'); channel.postMessage({ type: 'new_private_message', message: newMsg }); } safeSetStorage('tnhub_last_broadcast_msg', JSON.stringify({ time: Date.now(), message: newMsg })); } catch(e) {}
