const closePrivateChat = () => { if (privateChatUnsubscribe) { privateChatUnsubscribe(); privateChatUnsubscribe = null; } showPrivateChat.value = false; activeChatPartner.value = null; };
// ========================================== // TÍNH NĂNG ADMIN BLOGGER BLOCK CHAT DO VI PHẠM QUY ĐỊNH HỆ THỐNG // ========================================== const blockedChatUsers = ref([]); const showAdminBlockModal = ref(false); const targetUserToBlock = ref(null); const selectedBlockReason = ref('Spam tin nhắn / quảng cáo trái phép'); const customBlockReason = ref(''); const blockReasonPresets = [ 'Spam tin nhắn / quảng cáo trái phép', 'Ngôn từ thô tục, xúc phạm người khác', 'Gian lận, lừa đảo, giả mạo thông tin', 'Vi phạm quy định hệ thống TNHub', 'Lý do khác' ];
