const isUserChatBlocked = (userOrEmailOrId) => { if (!userOrEmailOrId) return false; let key = ''; if (typeof userOrEmailOrId === 'string') { key = userOrEmailOrId.toLowerCase().trim(); } else { key = (userOrEmailOrId.email || userOrEmailOrId.uid || userOrEmailOrId.id || '').toLowerCase().trim(); } if (!key) return false; if (key === BLOGGER_ADMIN_EMAIL.toLowerCase()) return false; return (blockedChatUsers.value || []).some(b => { const bEmail = (b.userEmail || '').toLowerCase().trim(); const bId = (b.userId || '').toLowerCase().trim(); return (bEmail && bEmail === key) || (bId && bId === key); }); };
